using System;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "RerollCounterOmenData", menuName = "Data/Battle/Omens System/Omen Data/Any/RerollCounter Omen Data")]
public class RerollCounterOmenData : OnRerollOmenData
{
	[Header("RerollCounterOmenData")]
	[SerializeField]
	private string everyXDiceRerolledTextID = "EveryXDiceRerolled";

	[SerializeField]
	private bool orrery;

	private OmenInstance omenInstance;

	public override void Initialize(OmenInstance omenInstance)
	{
		this.omenInstance = omenInstance;
		if (!KeepOmenCounterBetweenBattles)
		{
			ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.RestartEndBattleOmens.Add(omenInstance);
		}
		base.Initialize(omenInstance);
	}

	public override void OmenRemoved()
	{
		if (!KeepOmenCounterBetweenBattles)
		{
			ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.RestartEndBattleOmens.Remove(omenInstance);
		}
		base.OmenRemoved();
	}

	protected override Action<List<DiceInstance>> InitializeOmenAction(OmenInstance omenInstance)
	{
		return delegate(List<DiceInstance> diceInstances)
		{
			for (int i = 0; i < diceInstances.Count; i++)
			{
				ActivateOmen();
				if (base.Counter == 0)
				{
					omenInstance.EnqueueOmenFeedbackAndPlay();
				}
			}
			if (base.Counter == TriggerAmount - 1)
			{
				omenInstance.PlayBlinkingFeedback();
			}
			else
			{
				omenInstance.StopBlinkingFeedback();
			}
			omenInstance.UpdateOmenCounter();
		};
	}

	public override string OmenConvertedDescription()
	{
		return Smart.Format(ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString(everyXDiceRerolledTextID), TriggerAmount) + ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedSpace() + base.OmenConvertedDescription();
	}
}
